BEGIN TRANSACTION; WITH RECURSIVE c(i) AS (VALUES(2) UNION ALL SELECT i+1 FROM c WHERE i<50) INSERT INTO xyz SELECT i, '('||i||')' FROM c; INSERT INTO xyz VALUES(51, replace(hex(zeroblob(512)),'00',char(39)) || ' Hello ' || replace(hex(zeroblob(512)),'00',char(39))); INSERT INTO xyz VALUES(52,NULL); ROLLBACK; PRAGMA empty_result_callbacks=ON; CREATE TABLE query_result AS SELECT * FROM xyz WHERE b='Hi Y''all';